struct DynamicGpuTexture : GpuTexture {
  uint width = 0, height = 0;
  DXGI_FORMAT format = DXGI_FORMAT_UNKNOWN;
};
std::vector<std::uint8_t> ReadTexture(GpuContext& gpu,
                                      DynamicGpuTexture& source) {
  const auto description = source.resource->GetDesc();
  D3D12_PLACED_SUBRESOURCE_FOOTPRINT footprint{};
  UINT rows = 0; UINT64 row_size = 0, size = 0;
  gpu.device->GetCopyableFootprints(&description, 0, 1, 0, &footprint,
                                    &rows, &row_size, &size);
  auto readback = CreateBuffer(gpu.device.Get(), size, D3D12_HEAP_TYPE_READBACK,
      D3D12_RESOURCE_FLAG_NONE, D3D12_RESOURCE_STATE_COPY_DEST);
  Transition(gpu.list.Get(), source.resource.Get(), source.state,
             D3D12_RESOURCE_STATE_COPY_SOURCE);
  source.state = D3D12_RESOURCE_STATE_COPY_SOURCE;
  D3D12_TEXTURE_COPY_LOCATION from{}, to{};
  from.pResource = source.resource.Get();
  from.Type = D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;
  to.pResource = readback.Get(); to.Type = D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;
  to.PlacedFootprint = footprint;
  gpu.list->CopyTextureRegion(&to, 0, 0, 0, &from, nullptr); ExecuteAndReset(gpu);
  const std::size_t row = std::size_t{source.width} * source.bytes_per_pixel;
  std::vector<std::uint8_t> result(row * source.height); void* mapped = nullptr;
  D3D12_RANGE range{0, static_cast<SIZE_T>(size)}; readback->Map(0, &range, &mapped);
  for (uint y = 0; y < source.height; ++y)
    memcpy(result.data() + std::size_t{y} * row,
           static_cast<std::uint8_t*>(mapped) + std::size_t{y} * footprint.Footprint.RowPitch,
           row);
  readback->Unmap(0, nullptr); return result;
}
